//! Controlled tool-exposure planning (improvement plan §14): decides which MCP endpoints
//! and tools a generated task registers, and in which order, from the authentic pinned
//! definitions under `servers/snapshots`.
//!
//! `taskgen --exposure <variant>` turns a [`Plan`] into the agent's MCP server list, the
//! workspace connection inventory, and the registration directive the tools container
//! enforces (`mcp_tools::exposure`). The private [`ExposureManifest`] records what was
//! decided. The default full catalog produces no plan and changes no generated byte.
//!
//! A plan selects and orders; it never edits, renames or invents a definition. Grading
//! reads world state, so a plan that used other tools is never penalized for its path.

use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::Path,
};

use anyhow::{Context, bail};
use catalog::Catalog;
use mcp_tools::{
    exposure::{EndpointExposure, ExposureDirective, definition_sha256, sequence_sha256},
    snapshot::{Snapshot, o200k_count},
};
pub use mock_core::conditions::ExposureVariant;
use mock_core::conditions::{
    CatalogMetrics, CatalogStage, EXPOSURE_LIMITS, ExposedTool, ExposureManifest, InformationAxis,
    InformationDifference,
};
use serde_json::Value;
use sha2::{Digest, Sha256};

use crate::Scenario;

const BUDGET_BASIS: &str = "o200k_base_estimate_of_compact_tool_definitions";

struct PinnedTool {
    name: String,
    sha256: String,
    definition: Value,
}

struct PinnedEndpoint {
    id: String,
    service: String,
    tools: Vec<PinnedTool>,
    o200k: usize,
}

/// Every catalog endpoint's pinned tool definitions, in catalog order.
pub struct PinnedCatalog {
    endpoints: Vec<PinnedEndpoint>,
}

impl PinnedCatalog {
    pub fn load(root: &Path, catalog: &Catalog) -> anyhow::Result<Self> {
        let mut endpoints = Vec::new();
        for service in &catalog.services {
            for endpoint in &service.endpoints {
                let path = endpoint
                    .snapshot
                    .clone()
                    .unwrap_or_else(|| format!("servers/snapshots/{}.json", endpoint.id));
                let snapshot: Snapshot = serde_json::from_slice(
                    &fs::read(root.join(&path))
                        .with_context(|| format!("reading pinned tools for {}", endpoint.id))?,
                )
                .with_context(|| format!("invalid pinned tools for {}", endpoint.id))?;
                let mut names = BTreeSet::new();
                let tools = snapshot
                    .tools
                    .iter()
                    .map(|definition| {
                        let name = definition["name"]
                            .as_str()
                            .filter(|name| !name.is_empty() && names.insert((*name).to_owned()))
                            .with_context(|| {
                                format!("{} pins an unnamed or repeated tool", endpoint.id)
                            })?;
                        Ok(PinnedTool {
                            name: name.to_owned(),
                            sha256: definition_sha256(definition),
                            definition: definition.clone(),
                        })
                    })
                    .collect::<anyhow::Result<Vec<_>>>()?;
                if tools.is_empty() {
                    bail!("{} pins no tools", endpoint.id);
                }
                endpoints.push(PinnedEndpoint {
                    id: endpoint.id.clone(),
                    service: service.name.clone(),
                    tools,
                    o200k: snapshot.counts.o200k,
                });
            }
        }
        Ok(Self { endpoints })
    }

    fn stage<'a>(
        selection: impl IntoIterator<Item = (&'a PinnedEndpoint, &'a [usize])>,
    ) -> CatalogStage {
        let mut stage = CatalogStage {
            endpoints: 0,
            tools: 0,
            o200k_estimate: 0,
        };
        for (endpoint, tools) in selection {
            stage.endpoints += 1;
            stage.tools += tools.len();
            stage.o200k_estimate += if tools.len() == endpoint.tools.len() {
                endpoint.o200k
            } else {
                let definitions: Vec<&Value> = tools
                    .iter()
                    .map(|index| &endpoint.tools[*index].definition)
                    .collect();
                o200k_count(&serde_json::to_string(&definitions).expect("definitions serialize"))
            };
        }
        stage
    }
}

/// An exposure condition requested for a taskgen run.
pub struct Exposure {
    pub variant: ExposureVariant,
    pub seed: u64,
    /// Budget for `context_feasible`, as an offline `o200k_base` estimate.
    pub token_budget: Option<usize>,
    pub pinned: PinnedCatalog,
}

/// The realized registration for one task.
pub struct Plan {
    pub manifest: ExposureManifest,
    pub directive: ExposureDirective,
    /// Compact directive JSON, the exact value of the tools container variable.
    pub directive_json: String,
}

impl Plan {
    /// The catalog reduced to the registered endpoints in realized order, for the task's
    /// MCP server list and the workspace connection inventory.
    pub fn registered_catalog(&self, catalog: &Catalog) -> anyhow::Result<Catalog> {
        let services = self
            .manifest
            .endpoints
            .iter()
            .map(|id| {
                let (service, endpoint) = catalog.endpoint(id).context("registered endpoint")?;
                let mut service = service.clone();
                service.endpoints = vec![endpoint.clone()];
                Ok(service)
            })
            .collect::<anyhow::Result<_>>()?;
        Ok(Catalog { services })
    }
}

/// Hash of a realized `(endpoint, tool, definition hash)` registration sequence. The host
/// audit recomputes it from the `tools/list` responses the agent was actually served.
pub fn realized_catalog_sha256<'a>(
    tools: impl IntoIterator<Item = (&'a str, &'a str, &'a str)>,
) -> String {
    let mut digest = Sha256::new();
    for (endpoint, tool, definition) in tools {
        for part in [endpoint, tool, definition] {
            digest.update(part.as_bytes());
            digest.update([0]);
        }
    }
    format!(
        "sha256:{}",
        digest
            .finalize()
            .iter()
            .map(|byte| format!("{byte:02x}"))
            .collect::<String>()
    )
}

/// SplitMix64, seeded from the declared seed and the scenario so every task gets its own
/// reproducible order.
struct Random(u64);

impl Random {
    fn new(seed: u64, scenario: &str) -> Self {
        let digest = Sha256::digest(scenario.as_bytes());
        Self(seed ^ u64::from_be_bytes(digest[..8].try_into().expect("eight bytes")))
    }

    fn next(&mut self) -> u64 {
        self.0 = self.0.wrapping_add(0x9e37_79b9_7f4a_7c15);
        let mut value = self.0;
        value = (value ^ (value >> 30)).wrapping_mul(0xbf58_476d_1ce4_e5b9);
        value = (value ^ (value >> 27)).wrapping_mul(0x94d0_49bb_1331_11eb);
        value ^ (value >> 31)
    }

    fn shuffle<T>(&mut self, items: &mut [T]) {
        for index in (1..items.len()).rev() {
            items.swap(index, (self.next() % (index as u64 + 1)) as usize);
        }
    }
}

fn name_tokens(name: &str) -> BTreeSet<String> {
    let mut tokens = BTreeSet::new();
    let mut current = String::new();
    for character in name.chars() {
        if character.is_ascii_alphanumeric()
            && !(character.is_ascii_uppercase() && !current.is_empty())
        {
            current.push(character.to_ascii_lowercase());
        } else {
            if current.len() > 2 {
                tokens.insert(std::mem::take(&mut current));
            }
            current.clear();
            if character.is_ascii_alphanumeric() {
                current.push(character.to_ascii_lowercase());
            }
        }
    }
    if current.len() > 2 {
        tokens.insert(current);
    }
    tokens
}

/// Plans the registration for `scenario`. `None` means the default full catalog.
pub fn plan(exposure: &Exposure, scenario: &Scenario) -> anyhow::Result<Option<Plan>> {
    let pinned = &exposure.pinned.endpoints;
    let all = |endpoint: &PinnedEndpoint| (0..endpoint.tools.len()).collect::<Vec<_>>();
    let organization: Vec<usize> = pinned
        .iter()
        .enumerate()
        .filter(|(_, endpoint)| scenario.meta.services.contains(&endpoint.service))
        .map(|(index, _)| index)
        .collect();
    let reference: BTreeSet<(&str, &str)> = scenario
        .solution
        .calls
        .iter()
        .map(|call| (call.endpoint.as_str(), call.tool.as_str()))
        .collect();
    let mut random = Random::new(exposure.seed, &scenario.meta.id);
    let mut notes: Vec<(&str, String, String)> = Vec::new();
    // (endpoint index, tool indexes) in realized order.
    let selection: Vec<(usize, Vec<usize>)> = match exposure.variant {
        ExposureVariant::FullCatalog => return Ok(None),
        ExposureVariant::RelevantOnly => {
            if reference.is_empty() {
                bail!("{}: relevant_only needs a reference plan", scenario.meta.id);
            }
            notes.push((
                "selection_basis",
                "none".into(),
                "tools of the evaluator-owned reference plan".into(),
            ));
            pinned
                .iter()
                .enumerate()
                .filter_map(|(index, endpoint)| {
                    let tools: Vec<usize> = endpoint
                        .tools
                        .iter()
                        .enumerate()
                        .filter(|(_, tool)| {
                            reference.contains(&(endpoint.id.as_str(), tool.name.as_str()))
                        })
                        .map(|(tool, _)| tool)
                        .collect();
                    (!tools.is_empty()).then_some((index, tools))
                })
                .collect()
        }
        ExposureVariant::OrganizationPack => {
            notes.push((
                "selection_basis",
                "none".into(),
                "endpoints of the applications the scenario organization connects".into(),
            ));
            organization
                .iter()
                .map(|index| (*index, all(&pinned[*index])))
                .collect()
        }
        ExposureVariant::ContextFeasible => {
            let budget = exposure
                .token_budget
                .context("context_feasible needs --exposure-token-budget")?;
            let mut used: usize = organization.iter().map(|index| pinned[*index].o200k).sum();
            if used > budget {
                bail!(
                    "{}: the organization pack alone needs {used} estimated tokens, over the {budget} budget",
                    scenario.meta.id
                );
            }
            let mut chosen: BTreeSet<usize> = organization.iter().copied().collect();
            for (index, endpoint) in pinned.iter().enumerate() {
                if !chosen.contains(&index) && used + endpoint.o200k <= budget {
                    used += endpoint.o200k;
                    chosen.insert(index);
                }
            }
            notes.push((
                "selection_basis",
                "none".into(),
                format!(
                    "organization pack first, then catalog order while the estimate fits {budget} ({BUDGET_BASIS})"
                ),
            ));
            chosen
                .into_iter()
                .map(|index| (index, all(&pinned[index])))
                .collect()
        }
        ExposureVariant::RandomizedOrder => {
            let mut order: Vec<usize> = (0..pinned.len()).collect();
            random.shuffle(&mut order);
            notes.push(("endpoint_order", "catalog".into(), "seeded".into()));
            notes.push(("tool_order", "pinned".into(), "seeded".into()));
            order
                .into_iter()
                .map(|index| {
                    let mut tools = all(&pinned[index]);
                    random.shuffle(&mut tools);
                    (index, tools)
                })
                .collect()
        }
        ExposureVariant::ConfusingDistractors => {
            let pack: BTreeSet<String> = organization
                .iter()
                .flat_map(|index| pinned[*index].tools.iter())
                .flat_map(|tool| name_tokens(&tool.name))
                .collect();
            let mut candidates: Vec<(usize, u64, usize)> = pinned
                .iter()
                .enumerate()
                .filter(|(index, _)| !organization.contains(index))
                .map(|(index, endpoint)| {
                    let overlap = endpoint
                        .tools
                        .iter()
                        .filter(|tool| !name_tokens(&tool.name).is_disjoint(&pack))
                        .count();
                    (overlap, random.next(), index)
                })
                .filter(|(overlap, _, _)| *overlap > 0)
                .map(|(overlap, tie, index)| (index, tie, overlap))
                .collect();
            candidates.sort_by(|left, right| right.2.cmp(&left.2).then(left.1.cmp(&right.1)));
            let distractors: Vec<usize> = candidates
                .iter()
                .take(organization.len().max(2))
                .map(|(index, _, _)| *index)
                .collect();
            if distractors.is_empty() {
                bail!(
                    "{}: no authentic endpoint overlaps the organization pack",
                    scenario.meta.id
                );
            }
            notes.push((
                "distractor_endpoints",
                "none".into(),
                distractors
                    .iter()
                    .map(|index| pinned[*index].id.as_str())
                    .collect::<Vec<_>>()
                    .join(","),
            ));
            notes.push((
                "selection_basis",
                "none".into(),
                "organization pack plus authentic endpoints of other applications ranked by tool-name token overlap".into(),
            ));
            notes.push(("endpoint_order", "catalog".into(), "seeded".into()));
            let mut order: Vec<usize> = organization.iter().copied().chain(distractors).collect();
            random.shuffle(&mut order);
            order
                .into_iter()
                .map(|index| (index, all(&pinned[index])))
                .collect()
        }
    };
    if selection.is_empty() {
        bail!("{}: exposure registers no endpoint", scenario.meta.id);
    }

    let mut tools = Vec::new();
    let mut endpoints = Vec::new();
    let mut directive = ExposureDirective {
        schema_version: 1,
        endpoints: Vec::new(),
    };
    for (index, chosen) in &selection {
        let endpoint = &pinned[*index];
        endpoints.push(endpoint.id.clone());
        let registered: Vec<&PinnedTool> =
            chosen.iter().map(|tool| &endpoint.tools[*tool]).collect();
        let pinned_order = chosen.iter().copied().eq(0..endpoint.tools.len());
        directive.endpoints.push(EndpointExposure {
            id: endpoint.id.clone(),
            tools: (!pinned_order)
                .then(|| registered.iter().map(|tool| tool.name.clone()).collect()),
            sha256: sequence_sha256(
                registered
                    .iter()
                    .map(|tool| (tool.name.as_str(), tool.sha256.as_str())),
            ),
        });
        for tool in registered {
            tools.push(ExposedTool {
                endpoint: endpoint.id.clone(),
                tool: tool.name.clone(),
                definition_sha256: tool.sha256.clone(),
                position: tools.len(),
            });
        }
    }
    let directive_json = serde_json::to_string(&directive)?;
    let stored = CatalogStage {
        endpoints: pinned.len(),
        tools: pinned.iter().map(|endpoint| endpoint.tools.len()).sum(),
        o200k_estimate: pinned.iter().map(|endpoint| endpoint.o200k).sum(),
    };
    let registered = PinnedCatalog::stage(
        selection
            .iter()
            .map(|(index, chosen)| (&pinned[*index], chosen.as_slice())),
    );
    let registered_set: BTreeSet<(&str, &str)> = tools
        .iter()
        .map(|tool| (tool.endpoint.as_str(), tool.tool.as_str()))
        .collect();
    let hidden: Vec<&str> = pinned
        .iter()
        .filter(|endpoint| !endpoints.contains(&endpoint.id))
        .map(|endpoint| endpoint.id.as_str())
        .collect();
    let mut differences: BTreeMap<&str, (String, String)> = BTreeMap::from([
        (
            "registered_endpoints",
            (
                stored.endpoints.to_string(),
                registered.endpoints.to_string(),
            ),
        ),
        (
            "registered_tools",
            (stored.tools.to_string(), registered.tools.to_string()),
        ),
        (
            "hidden_endpoints",
            (
                "none".into(),
                if hidden.is_empty() {
                    "none".into()
                } else {
                    hidden.join(",")
                },
            ),
        ),
        (
            "workspace_connection_inventory",
            (
                "every catalog endpoint".into(),
                "registered endpoints only, in realized order".into(),
            ),
        ),
    ]);
    for (item, a, b) in notes {
        differences.insert(item, (a, b));
    }
    let information_differences = differences
        .into_iter()
        .filter(|(_, (a, b))| a != b)
        .map(|(item, (a, b))| InformationDifference {
            axis: InformationAxis::Exposure,
            item: item.into(),
            a,
            b,
        })
        .collect();
    let manifest = ExposureManifest {
        schema_version: 1,
        variant: exposure.variant,
        seed: exposure.seed,
        token_budget: (exposure.variant == ExposureVariant::ContextFeasible)
            .then_some(exposure.token_budget)
            .flatten(),
        budget_basis: (exposure.variant == ExposureVariant::ContextFeasible)
            .then(|| BUDGET_BASIS.to_owned()),
        catalog_sha256: realized_catalog_sha256(tools.iter().map(|tool| {
            (
                tool.endpoint.as_str(),
                tool.tool.as_str(),
                tool.definition_sha256.as_str(),
            )
        })),
        directive_sha256: mock_core::runner::sha256(directive_json.as_bytes()),
        metrics: CatalogMetrics {
            stored,
            registered,
            provider_accepted: None,
            model_visible: None,
            loaded: None,
        },
        information_differences,
        reference_plan_registered: reference.iter().all(|call| registered_set.contains(call)),
        diagnostic: exposure.variant == ExposureVariant::RelevantOnly,
        limits: EXPOSURE_LIMITS.map(str::to_owned).to_vec(),
        endpoints,
        tools,
    };
    Ok(Some(Plan {
        manifest,
        directive,
        directive_json,
    }))
}
